B.c29=new A.t("ondemandUrl",B.K,"Opt-in on-demand build endpoint: while panning outside pre-built coverage, polls this base URL every ~3s (60s cap) to build transit data for the viewport live. Unset keeps build-on-pan off.",B.e,null)
