B.cgC=new A.t("id",B.K,"This node's handle \u2014 required for the mapSetLayerVisible / mapSetFilter / mapSetPaint runtime actions to target it (an id-less glmap still renders, just not runtime-controllable).",B.e,null)
B.c9W=new A.t("table",B.az,"Marker source table (optional when tiles/geojsonSources is set).",B.e,null)
