B.c4t=new A.t("flowsTable",B.az,'Flows table (default "flows").',B.e,null)
B.cbx=new A.t("scope",B.K,"The board (file) id to scope screens to \u2014 typically injected by the hosting library-explorer node. Absent shows every screen row.",B.e,null)
