B.bWK=new A.cJ("sidescroller","A real-time side-scrolling platformer with its own game loop (joystick + jump/attack); optional high-score persistence.",B.b4Z,!1)
B.cdW=new A.t("cols",B.al,"Grid columns (default 36).",B.e,null)
B.cdJ=new A.t("rows",B.al,"Grid rows (default 24).",B.e,null)
